from __future__ import annotations

import ast

from .models import Finding

_MUTABLE_LITERALS = (ast.List, ast.Dict, ast.Set)
_DANGEROUS_CALLS = {"eval", "exec"}
_BROAD_EXCEPTIONS = {"Exception", "BaseException"}


class RuleVisitor(ast.NodeVisitor):
    def __init__(self, path: str, long_function_lines: int = 40) -> None:
        self.path = path
        self.long_function_lines = long_function_lines
        self.imports: dict[str, tuple[int, str]] = {}
        self.used_names: set[str] = set()
        self.findings: list[Finding] = []

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            bound_name = alias.asname or alias.name.split(".")[0]
            self.imports[bound_name] = (node.lineno, alias.name)
        self.generic_visit(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        for alias in node.names:
            if alias.name == "*":
                continue
            bound_name = alias.asname or alias.name
            self.imports[bound_name] = (node.lineno, alias.name)
        self.generic_visit(node)

    def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Load):
            self.used_names.add(node.id)
        self.generic_visit(node)

    def _check_function(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
        defaults = [*node.args.defaults, *[value for value in node.args.kw_defaults if value is not None]]
        if any(isinstance(default, _MUTABLE_LITERALS) for default in defaults):
            self.findings.append(
                Finding(
                    self.path,
                    node.lineno,
                    "MUTABLE_DEFAULT",
                    f"Function '{node.name}' uses a mutable default argument",
                )
            )

        end_line = getattr(node, "end_lineno", node.lineno) or node.lineno
        line_count = end_line - node.lineno + 1
        if line_count > self.long_function_lines:
            self.findings.append(
                Finding(
                    self.path,
                    node.lineno,
                    "LONG_FUNCTION",
                    f"Function '{node.name}' is {line_count} lines long (limit {self.long_function_lines})",
                )
            )

        self.generic_visit(node)

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self._check_function(node)

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
        self._check_function(node)

    def visit_ExceptHandler(self, node: ast.ExceptHandler) -> None:
        broad = node.type is None or (
            isinstance(node.type, ast.Name) and node.type.id in _BROAD_EXCEPTIONS
        )
        if broad:
            self.findings.append(
                Finding(
                    self.path,
                    node.lineno,
                    "BROAD_EXCEPTION",
                    "Avoid bare except or catching Exception/BaseException without narrowing the error",
                )
            )
        self.generic_visit(node)

    def visit_Call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Name) and node.func.id in _DANGEROUS_CALLS:
            self.findings.append(
                Finding(
                    self.path,
                    node.lineno,
                    "DANGEROUS_CALL",
                    f"Use of '{node.func.id}' can execute arbitrary code",
                    "error",
                )
            )
        self.generic_visit(node)

    def finalize(self) -> list[Finding]:
        for bound_name, (line, imported_name) in self.imports.items():
            if bound_name not in self.used_names:
                self.findings.append(
                    Finding(
                        self.path,
                        line,
                        "UNUSED_IMPORT",
                        f"Imported name '{imported_name}' is never used",
                    )
                )
        return sorted(self.findings, key=lambda finding: (finding.line, finding.code, finding.message))

