from __future__ import annotations

from dataclasses import asdict, dataclass


@dataclass(frozen=True, order=True)
class Finding:
    path: str
    line: int
    code: str
    message: str
    severity: str = "warning"

    def to_dict(self) -> dict[str, str | int]:
        return asdict(self)
